package com.airesumebuilder.feature.subscription.entity;
import jakarta.persistence.*; import java.math.BigDecimal; import java.time.Instant; import lombok.*;
@Entity @Table(name="payment_transactions",uniqueConstraints=@UniqueConstraint(name="uk_payment_transactions_reference",columnNames={"provider","provider_reference"})) @Getter @Setter @NoArgsConstructor
public class PaymentTransaction { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @ManyToOne(fetch=FetchType.LAZY,optional=false) @JoinColumn(name="subscription_id",nullable=false) private Subscription subscription; @Column(nullable=false,length=80) private String provider; @Column(name="provider_reference",nullable=false,length=255) private String providerReference; @Column(nullable=false,precision=12,scale=2) private BigDecimal amount; @Column(nullable=false,length=3) private String currency; @Column(nullable=false,length=30) private String status; @Column(name="occurred_at",nullable=false,updatable=false) private Instant occurredAt; @PrePersist void create(){if(occurredAt==null)occurredAt=Instant.now();} }
